function getTopicsByLevel(level) {
  return GRAMMAR_TOPICS.filter(t => t.level === level);
}

function getTopicById(id) {
  return GRAMMAR_TOPICS.find(t => t.id === id);
}

/* ═══ Button.jsx ═══ */
const VARIANTS = {
  primary:   { background: "linear-gradient(135deg, #6C5CE7, #7C4DFF)", color: "#fff",  border: "none",               shadow: "0 4px 16px rgba(108,92,231,.4)" },
  secondary: { background: "var(--surf-2)", color: "var(--text)", border: "1.5px solid var(--border)", shadow: "none" },
  ghost:     { background: "transparent",   color: "var(--text-2)", border: "none",        shadow: "none" },
  danger:    { background: "var(--red)",    color: "#fff",  border: "none",               shadow: "0 4px 12px rgba(239,68,68,.35)" },
  success:   { background: "var(--green)",  color: "#fff",  border: "none",               shadow: "0 4px 12px rgba(34,197,94,.35)" },
  outline:   { background: "transparent",   color: "var(--accent)", border: "1.5px solid var(--accent)", shadow: "none" },
};

const SIZES = {
  sm: { padding: "8px 16px",  fontSize: 13, borderRadius: 12, height: 36 },
  md: { padding: "12px 22px", fontSize: 14, borderRadius: 16, height: 44 },
  lg: { padding: "14px 28px", fontSize: 15, borderRadius: 16, height: 50 },
};

const Button = memo(function Button({
  children,
  variant = "primary",
  size    = "md",
  icon,
  onClick,
  disabled,
  loading,
  full,
  style = {},
}) {
  const v = VARIANTS[variant] || VARIANTS.primary;
  const s = SIZES[size]       || SIZES.md;

  return (
    <button
      onClick={disabled || loading ? undefined : onClick}
      style={{
        display:        "inline-flex",
        alignItems:     "center",
        justifyContent: "center",
        gap:            7,
        cursor:         disabled || loading ? "not-allowed" : "pointer",
        opacity:        disabled ? 0.5 : 1,
        fontFamily:     "'Inter', sans-serif",
        fontWeight:     600,
        letterSpacing:  "0.01em",
        transition:     "all .18s cubic-bezier(.4,0,.2,1)",
        width:          full ? "100%" : "auto",
        ...v,
        ...s,
        boxShadow:      v.shadow,
        ...style,
      }}
      className="btn-press"
    >
      {loading ? (
        <div style={{
          width: 16, height: 16, borderRadius: "50%",
          border: "2.5px solid rgba(255,255,255,.3)",
          borderTopColor: "currentColor",
          animation: "spin .7s linear infinite",
        }} />
      ) : (
        icon && <span style={{ fontSize: size === "sm" ? 14 : 17, lineHeight: 1 }}>{icon}</span>
      )}
      {children}
    </button>
  );
});

/* ═══ Card.jsx ═══ */
const Card = memo(function Card({
  children,
  padding = "20px",
  hover   = false,
  onClick,
  style   = {},
  accent,
  glass   = false,
}) {
  return (
    <div
      onClick={onClick}
      className={hover ? "card-hover" : ""}
      style={{
        background:   glass ? "var(--glass)" : "var(--surf)",
        backdropFilter: glass ? "blur(20px)" : "none",
        border:       accent ? `1.5px solid ${accent}35` : "1px solid var(--border)",
        borderRadius: 24,
        padding,
        boxShadow:    "var(--shadow-card)",
        cursor:       onClick ? "pointer" : "default",
        transition:   "all .25s cubic-bezier(.4,0,.2,1)",
        ...style,
      }}
    >
      {children}
    </div>
  );
});

/* ═══ MicRecorder.jsx ═══ */
const MicRecorder = memo(function MicRecorder({
  recording,
  onStart,
  onStop,
  disabled = false,
  size = 64,
  color = "var(--accent)",
}) {
  const handleClick = () => {
    if (disabled) return;
    recording ? onStop() : onStart();
  };

  return (
    <div style={{ position:"relative", display:"flex", alignItems:"center", justifyContent:"center" }}>
      {/* Pulse rings when recording */}
      {recording && (
        <>
          <div style={{ position:"absolute", width:size*1.8, height:size*1.8, borderRadius:"50%", background:"rgba(239,68,68,.12)", animation:"glowPulse 1.6s ease infinite", pointerEvents:"none" }} />
          <div style={{ position:"absolute", width:size*1.45, height:size*1.45, borderRadius:"50%", background:"rgba(239,68,68,.18)", animation:"glowPulse 1.6s ease .3s infinite", pointerEvents:"none" }} />
        </>
      )}
      <button
        onClick={handleClick}
        className="btn-press"
        style={{
          width:          size,
          height:         size,
          borderRadius:   "50%",
          border:         "none",
          cursor:         disabled ? "not-allowed" : "pointer",
          fontSize:       Math.round(size * 0.38),
          background:     recording
            ? "linear-gradient(135deg, #EF4444, #DC2626)"
            : `linear-gradient(135deg, ${color}, ${color}cc)`,
          display:        "flex",
          alignItems:     "center",
          justifyContent: "center",
          boxShadow:      recording
            ? "0 4px 24px rgba(239,68,68,.45)"
            : `0 6px 24px ${color}55`,
          animation:      recording ? "recPulse 1.5s ease infinite" : "none",
          transition:     "all .25s cubic-bezier(.4,0,.2,1)",
          opacity:        disabled ? 0.4 : 1,
          flexShrink:     0,
          position:       "relative",
          zIndex:         1,
        }}
        aria-label={recording ? "Stop recording" : "Start recording"}
      >
        {recording ? "⏹" : "🎙"}
      </button>
    </div>
  );
});

/* ═══ ProgressBar.jsx ═══ */
const ProgressBar = memo(function ProgressBar({
  value,
  max     = 100,
  color   = "var(--accent)",
  height  = 6,
  label,
  showPct = true,
  style   = {},
}) {
  const pct = Math.min(100, Math.max(0, Math.round((value / max) * 100)));

  return (
    <div style={{ ...style }}>
      {(label || showPct) && (
        <div style={{
          display:        "flex",
          justifyContent: "space-between",
          marginBottom:   5,
          fontSize:       12,
          color:          "var(--text-2)",
        }}>
          {label && <span>{label}</span>}
          {showPct && <span style={{ fontWeight: 700, color }}>{pct}%</span>}
        </div>
      )}
      <div style={{
        height,
        background:   "var(--border-2)",
        borderRadius: height,
        overflow:     "hidden",
      }}>
        <div style={{
          height:       "100%",
          width:        `${pct}%`,
          background:   color,
          borderRadius: height,
          transition:   "width 1s cubic-bezier(.4,0,.2,1)",
        }} />
      </div>
    </div>
  );
});


/* Score ring for pronunciation results */
const ScoreRing = memo(function ScoreRing({ score, size = 96 }) {
  const r     = 38;
  const circ  = 2 * Math.PI * r;
  const dash  = (score / 100) * circ;
  const color = score >= 80 ? "var(--green)" : score >= 55 ? "var(--gold)" : "var(--red)";
  const grade = score >= 90 ? "Outstanding" : score >= 80 ? "Excellent" : score >= 65 ? "Good" : score >= 50 ? "Decent" : "Keep Going";

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
      <svg width={size} height={size}>
        <circle
          cx={size / 2} cy={size / 2} r={r}
          fill="none" stroke="var(--border-2)" strokeWidth={7}
        />
        <circle
          cx={size / 2} cy={size / 2} r={r}
          fill="none" stroke={color} strokeWidth={7}
          strokeDasharray={circ}
          strokeDashoffset={circ - dash}
          strokeLinecap="round"
          transform={`rotate(-90 ${size / 2} ${size / 2})`}
          style={{
            transition: "stroke-dashoffset 1.2s cubic-bezier(.4,0,.2,1)",
            filter:     `drop-shadow(0 0 6px ${color}60)`,
          }}
        />
        <text x={size / 2} y={size / 2 - 4} textAnchor="middle"
          fill="var(--text)" fontSize="20" fontWeight="700"
          fontFamily="'Poppins',sans-serif">
          {score}
        </text>
        <text x={size / 2} y={size / 2 + 14} textAnchor="middle"
          fill="var(--text-3)" fontSize="9" fontFamily="'Inter',sans-serif">
          / 100
        </text>
      </svg>
      <span style={{ fontSize: 10, fontWeight: 800, color, letterSpacing: ".07em" }}>
        {grade.toUpperCase()}
      </span>
    </div>
  );
});


/* Word token for pronunciation feedback */
const WordToken = memo(function WordToken({ word, status, said }) {
  const config = {
    correct: { color: "var(--green)", bg: "rgba(34,197,94,.1)",  border: "rgba(34,197,94,.3)" },
    close:   { color: "var(--gold)",  bg: "rgba(234,179,8,.1)",  border: "rgba(234,179,8,.3)" },
    wrong:   { color: "var(--red)",   bg: "rgba(239,68,68,.1)",  border: "rgba(239,68,68,.3)" },
    missing: { color: "var(--orange)",bg: "rgba(249,115,22,.1)", border: "rgba(249,115,22,.3)" },
  };
  const cfg = config[status];
  if (!cfg) return <span style={{ fontSize: 17, fontFamily: "'Poppins',sans-serif", margin: "0 2px" }}>{word}</span>;

  return (
    <span title={said ? `You said: "${said}"` : undefined} style={{
      display:        "inline-block",
      padding:        "2px 7px",
      margin:         "2px",
      borderRadius:   7,
      background:     cfg.bg,
      border:         `1.5px solid ${cfg.border}`,
      color:          cfg.color,
      fontSize:       17,
      fontFamily:     "'Poppins',sans-serif",
      textDecoration: status === "wrong" ? `underline wavy ${cfg.color}` : "none",
      cursor:         said ? "help" : "default",
    }}>
      {word}
    </span>
  );
});

