// Get today's word - uses stored seed so same device sees same word per day
// but picks truly randomly from full pool (not rotating the same 7)
function getDailyWord() {
  const today = new Date();
  const dateKey = `${today.getFullYear()}-${today.getMonth()}-${today.getDate()}`;
  // Simple deterministic hash of date → index into large pool
  let hash = 0;
  for (let i = 0; i < dateKey.length; i++) {
    hash = (Math.imul(31, hash) + dateKey.charCodeAt(i)) | 0;
  }
  const idx = Math.abs(hash) % WOTD_POOL.length;
  return WOTD_POOL[idx];
}

const WotdCard = memo(function WotdCard({ settings = {}, dispatch }) {
  const w = getDailyWord();
  const [flipped, setFlipped] = useState(false);
  const tts = useTTS();

  // FIX: dynamic translation based on global language setting
  const currentLang  = settings.lang || "ml";
  const [wotdTranslation, setWotdTranslation] = useState(w.translation);
  const [wotdTranslating, setWotdTranslating] = useState(false);
  const prevLangRef  = useRef(currentLang); // track previous to detect real changes

  useEffect(() => {
    const langChanged = prevLangRef.current !== currentLang;
    prevLangRef.current = currentLang;

    if (currentLang === "ml") {
      setWotdTranslation(w.translation);
      // Speak word aloud when switching TO Malayalam
      return;
    }
    let cancelled = false;
    setWotdTranslating(true);
    translateText(w.word, currentLang)
      .then(t => {
        if (cancelled) return;
        setWotdTranslation(t || w.translation);
        // Speak word when language actually changes (not on first mount)
      })
      .catch(() => { if (!cancelled) setWotdTranslation(w.translation); })
      .finally(() => { if (!cancelled) setWotdTranslating(false); });
    return () => { cancelled = true; };
  }, [currentLang, w.word, w.translation]);

  const speakWord = (e) => {
    e.stopPropagation();
    tts.speak(`${w.word}. ${w.meaning}. Example: ${w.example}`, {
      lang:  settings.accent || "en-US",
      rate:  0.88,
      pitch: 1,
    });
  };

  const [randomSeed, setRandomSeed] = useState(0);
  const displayWord = randomSeed === 0 ? w : WOTD_POOL[(Math.abs((getDailyWord().word.length * 17 + randomSeed * 31)) % WOTD_POOL.length + randomSeed) % WOTD_POOL.length];

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
        <span style={{ fontFamily:"'Poppins',sans-serif", fontSize:13, fontWeight:700, color:"var(--text)" }}>📖 Word of the Day</span>
        <div style={{ display:"flex", gap:6 }}>
          <button onClick={() => setRandomSeed(s => (s+1) % WOTD_POOL.length)}
            style={{ fontSize:11, fontWeight:700, padding:"4px 11px", borderRadius:20, background:"var(--surf-2)", border:"1px solid var(--border)", cursor:"pointer", color:"var(--text-2)" }}>
            🔀 New Word
          </button>
          {dispatch && (
            <button onClick={() => dispatch({ type:"SET_SCREEN", payload:"dictionary" })}
              style={{ fontSize:11, fontWeight:700, padding:"4px 11px", borderRadius:20, background:"var(--accent-soft)", border:"1px solid var(--accent-border)", cursor:"pointer", color:"var(--accent)" }}>
              Learn More →
            </button>
          )}
        </div>
      </div>
      <div style={{ position:"relative", cursor:"pointer", perspective:1000, height:170 }}>
        <button
          onClick={speakWord}
          style={{
            position:"absolute", top:10, right:10, zIndex:10,
            width:36, height:36, borderRadius:12,
            background:"rgba(255,255,255,0.18)",
            border:"1.5px solid rgba(255,255,255,0.35)",
            cursor:"pointer",
            display:"flex", alignItems:"center", justifyContent:"center",
            color:"#fff", gap:4, backdropFilter:"blur(4px)",
            transition:"all .2s",
          }}
          title="Listen to pronunciation"
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>
            <path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>
            <path d="M15.54 8.46a5 5 0 0 1 0 7.07"/>
          </svg>
        </button>
        <div
          onClick={function(){ setFlipped(function(f){ return !f; }); }}
          style={{ height:"100%" }}
        >
          <div style={{
            position:"relative", height:"100%", transformStyle:"preserve-3d",
            transform: flipped ? "rotateY(180deg)" : "none",
            transition:"transform .6s",
          }}>
            <div style={{
              position:"absolute", inset:0, backfaceVisibility:"hidden",
              background:"linear-gradient(135deg, var(--accent), var(--blue))",
              borderRadius:18, padding:"18px 20px",
              display:"flex", flexDirection:"column", justifyContent:"space-between",
            }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                  <span style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.7)", textTransform:"uppercase" }}>Word of the Day</span>
                  <span style={{ fontSize:9, fontWeight:800, padding:"1px 7px", borderRadius:20, background:"rgba(255,255,255,.2)", color:"#fff" }}>{displayWord.cefr}</span>
                </div>
                <span style={{ fontSize:10, color:"rgba(255,255,255,.6)" }}>Tap to reveal</span>
              </div>
              <div>
                <div style={{ fontFamily:"'Poppins',sans-serif", fontSize:30, fontWeight:700, color:"#fff", marginBottom:3 }}>{displayWord.word}</div>
                <div style={{ fontSize:12, color:"rgba(255,255,255,.75)", fontStyle:"italic" }}>{displayWord.ipa} · {displayWord.pos}</div>
              </div>
              <div style={{ fontSize:11, color:"rgba(255,255,255,.55)" }}>Tap card to see meaning</div>
            </div>
            <div style={{
              position:"absolute", inset:0, backfaceVisibility:"hidden",
              transform:"rotateY(180deg)",
              background:"linear-gradient(135deg, var(--blue), var(--accent))",
              borderRadius:18, padding:"18px 20px",
              display:"flex", flexDirection:"column", justifyContent:"space-between",
            }}>
              <div style={{ fontSize:10, fontWeight:700, color:"rgba(255,255,255,.7)", textTransform:"uppercase" }}>Meaning</div>
              <div>
                <div style={{ fontFamily:"'Poppins',sans-serif", fontSize:17, color:"#fff", marginBottom:6, lineHeight:1.4 }}>{displayWord.meaning}</div>
                <div style={{ fontSize:12, color:"rgba(255,255,255,.85)", fontStyle:"italic" }}>{displayWord.example}</div>
              </div>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <span style={{ fontSize:13, color:"rgba(255,255,255,.9)", fontWeight:600 }}>
                  {wotdTranslating
                    ? <span style={{ fontSize:11, color:"rgba(255,255,255,.6)" }}>Translating...</span>
                    : wotdTranslation
                  }
                </span>
                <span style={{ fontSize:10, color:"rgba(255,255,255,.55)" }}>Tap to flip back</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
});

