/* ─────────────────────────────────────────────────────────────
   AI SVG GENERATOR — calls Claude API to create unique illustration
─────────────────────────────────────────────────────────────── */
async function generateSceneSVG(scene, level) {
  const levelGuide = {
    A1: "simple, bright, cheerful, one or two people or objects, clear action, minimal background",
    A2: "everyday social situation, 2-3 people interacting, familiar location like café or classroom",
    B1: "group activity or workplace, 3-5 people, professional or social context, visible emotion",
    B2: "complex scene with multiple story elements, nuanced emotion, rich environment detail",
  };

  const prompt = `Create a colourful SVG illustration for an English language learning app.

Scene: "${scene}"
Level: ${level} — Style: ${levelGuide[level] || levelGuide.B1}

Requirements:
- viewBox="0 0 360 300"
- Use bright, friendly colours (not dark/scary)
- Draw people as simple but expressive cartoon figures with round heads, coloured hair, simple facial features (dot eyes, curved smile), and coloured clothing
- Include a background matching the scene (sky, room, street, etc.)
- Add at least 1-2 recognisable objects related to the scene
- Bottom: add a text label showing the scene name (fontSize="12" fill="#555" fontFamily="Inter,sans-serif" y="292")
- Return ONLY the raw SVG code starting with <svg and ending with </svg>
- No markdown, no explanation, no backticks — pure SVG only`;

  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-20250514",
        max_tokens: 1800,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    const data = await res.json();
    const raw = data?.content?.[0]?.text || "";
    // Extract SVG from response
    const match = raw.match(/<svg[\s\S]*<\/svg>/i);
    return match ? match[0] : null;
  } catch {
    return null;
  }
}

