const SCENE_EMOJIS = { "smiling":"😊", "eating":"🍽️", "reading":"📚", "dog":"🐕", "playing":"⚽", "breakfast":"🍳", "coffee":"☕", "friends":"👥", "walking":"🚶", "family":"👨‍👩‍👧", "gym":"💪", "cooking":"👨‍🍳", "students":"📚", "park":"🌳", "supermarket":"🛒", "tourists":"✈️", "doctor":"🏥", "market":"🏪", "transport":"🚂", "office":"💼", "restaurant":"🍴", "airport":"✈️", "volunteers":"🤝", "businessman":"👔", "jogging":"🏃", "meeting":"🤝", "meal":"🥗", "city":"🌆", "collaborating":"👥", "boardroom":"🏢", "discussion":"💬", "laptop":"💻", "university":"🎓", "landscape":"🌄", "conference":"🎤", "medical":"⚕️", "firefighters":"🚒", "night market":"🌙", "planning":"📋" };
function getSceneEmoji(scene) { const s=scene.toLowerCase(); for(const [k,v] of Object.entries(SCENE_EMOJIS)){ if(s.includes(k)) return v; } return "🖼️"; }

const SCENE_GRADIENTS = ["linear-gradient(135deg,#667eea,#764ba2)","linear-gradient(135deg,#f093fb,#f5576c)","linear-gradient(135deg,#4facfe,#00f2fe)","linear-gradient(135deg,#43e97b,#38f9d7)","linear-gradient(135deg,#fa709a,#fee140)","linear-gradient(135deg,#a18cd1,#fbc2eb)","linear-gradient(135deg,#ffecd2,#fcb69f)","linear-gradient(135deg,#96fbc4,#f9f586)","linear-gradient(135deg,#fccb90,#d57eeb)","linear-gradient(135deg,#e0c3fc,#8ec5fc)"];

const SmartImage = React.memo(function SmartImage({ src, alt, style = {}, sceneText = "" }) {
  const [status, setStatus] = React.useState("loading"); // loading | loaded | error
  const gradIdx = React.useMemo(() => Math.abs((sceneText||"").split("").reduce((a,c)=>a+c.charCodeAt(0),0)) % SCENE_GRADIENTS.length, [sceneText]);

  const ScenePlaceholder = () => (
    <div style={{ width:"100%", aspectRatio:"16/9", background:SCENE_GRADIENTS[gradIdx], display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:10, ...style }}>
      <span style={{ fontSize:52, filter:"drop-shadow(0 4px 8px rgba(0,0,0,.3))", animation:"floatY 2s ease-in-out infinite" }}>{getSceneEmoji(sceneText||alt||"")}</span>
      <div style={{ fontSize:12, color:"rgba(255,255,255,.9)", fontWeight:700, textAlign:"center", padding:"0 20px", lineHeight:1.4, textShadow:"0 1px 4px rgba(0,0,0,.4)", maxWidth:240 }}>{sceneText||alt||"Scene"}</div>
    </div>
  );

  if (!src) return <ScenePlaceholder />;

  return (
    <div style={{ position:"relative", overflow:"hidden", ...style }}>
      {status === "loading" && (
        <div style={{ position:"absolute", inset:0 }}><ScenePlaceholder /></div>
      )}
      {status !== "error" && (
        <img src={src} alt={alt||"Scene"} draggable={false} loading="lazy" decoding="async"
          onLoad={() => setStatus("loaded")}
          onError={() => setStatus("error")}
          style={{ width:"100%", display:"block", objectFit:"cover", aspectRatio:"16/9",
            filter:    status==="loaded"?"none":"blur(12px)",
            transform: status==="loaded"?"scale(1)":"scale(1.04)",
            transition:"filter .5s ease, transform .5s ease",
            opacity:   status==="loaded"?1:0,
          }}
        />
      )}
      {status === "error" && <ScenePlaceholder />}
    </div>
  );
});

const ZoomableImage = ({ imageUrl, sceneId, level, scene, onNext, onPrev, imgIndex=0, imgTotal=10 }) => {
  const [zoom,   setZoom]   = React.useState(1);
  const [panX,   setPanX]   = React.useState(0);
  const [panY,   setPanY]   = React.useState(0);
  const [zoomed, setZoomed] = React.useState(false);
  const lastTap  = React.useRef(0);
  const pinchRef = React.useRef(null);
  const wrapRef  = React.useRef(null);

  const resetZoom = () => { setZoom(1); setPanX(0); setPanY(0); setZoomed(false); };

  const handleDoubleTap = (e) => {
    const now = Date.now();
    if (now - lastTap.current < 300) {
      e.preventDefault();
      if (zoomed) { resetZoom(); return; }
      const rect = wrapRef.current?.getBoundingClientRect();
      if (rect) {
        const cx = (e.touches?.[0]?.clientX || e.clientX) - rect.left - rect.width / 2;
        const cy = (e.touches?.[0]?.clientY || e.clientY) - rect.top  - rect.height / 2;
        setZoom(2.8); setPanX(-cx * 0.9); setPanY(-cy * 0.9); setZoomed(true);
      }
    }
    lastTap.current = now;
  };

  const onPinchStart = (e) => {
    if (e.touches.length === 2) {
      const d = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
      pinchRef.current = { d, zoom };
    }
  };
  const onPinchMove = (e) => {
    if (e.touches.length === 2 && pinchRef.current) {
      e.preventDefault();
      const d = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
      const nz = Math.min(4, Math.max(1, pinchRef.current.zoom * d / pinchRef.current.d));
      setZoom(nz); setZoomed(nz > 1.1);
    }
  };
  const onPinchEnd = () => { pinchRef.current = null; if (zoom < 1.1) resetZoom(); };
  const lc = LEVEL_COLORS[level] || "var(--accent)";

  return (
    <div style={{ position:"relative", borderRadius:24, overflow:"hidden",
      boxShadow:"0 8px 32px rgba(108,92,231,.2)", background:"#111",
      marginBottom:12, userSelect:"none" }}>
      {!zoomed && (
        <div style={{ position:"absolute", top:10, right:10, zIndex:10, pointerEvents:"none",
          background:"rgba(0,0,0,.5)", backdropFilter:"blur(6px)", borderRadius:999,
          padding:"4px 10px", fontSize:10, fontWeight:600, color:"rgba(255,255,255,.85)",
          display:"flex", gap:4, alignItems:"center" }}>
          🔍 Double-tap to zoom
        </div>
      )}
      {zoomed && (
        <button onClick={resetZoom} style={{ position:"absolute", top:10, right:10, zIndex:10,
          background:"rgba(108,92,231,.9)", border:"none", borderRadius:999,
          padding:"5px 13px", fontSize:11, fontWeight:700, color:"#fff", cursor:"pointer" }}>
          ✕ Reset
        </button>
      )}
      <div ref={wrapRef}
        onTouchStart={(e) => { handleDoubleTap(e); onPinchStart(e); }}
        onTouchMove={onPinchMove} onTouchEnd={onPinchEnd}
        onClick={handleDoubleTap}
        style={{ overflow:"hidden", touchAction: zoomed ? "none" : "pan-y", cursor: zoomed ? "grab" : "zoom-in" }}>
        <div style={{
          transform:`scale(${zoom}) translate(${panX/zoom}px,${panY/zoom}px)`,
          transformOrigin:"center center",
          transition: pinchRef.current ? "none" : "transform .22s ease",
          lineHeight:0,
        }}>
          {imageUrl
            ? <SmartImage src={imageUrl} alt={scene} sceneText={scene} style={{ aspectRatio:"16/9" }} />
            : <SmartImage src={null} alt={scene} sceneText={scene} style={{ aspectRatio:"16/9" }} />
          }
        </div>
      </div>
      <div style={{ position:"absolute", bottom:0, left:0, right:0,
        background:"linear-gradient(transparent,rgba(0,0,0,.78))",
        padding:"32px 16px 14px", borderRadius:"0 0 24px 24px",
        opacity: zoomed ? 0 : 1, transition:"opacity .2s",
        pointerEvents: zoomed ? "none" : "all" }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-end" }}>
          <div style={{ flex:1 }}>
            <span style={{ fontSize:11, fontWeight:800, padding:"4px 11px", borderRadius:999,
              background:lc, color:"#fff", marginBottom:5, display:"inline-block",
              boxShadow:`0 2px 8px ${lc}60` }}>{level} Level</span>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:4, flexWrap:"wrap" }}>
              <div style={{ fontSize:12, color:"rgba(255,255,255,.9)", fontStyle:"italic", lineHeight:1.5, flex:1 }}>{scene}</div>
              {imgTotal > 1 && <div style={{ fontSize:10, fontWeight:800, color:"rgba(255,255,255,.75)", background:"rgba(0,0,0,.4)", padding:"2px 8px", borderRadius:999, whiteSpace:"nowrap", flexShrink:0 }}>{imgIndex + 1}/{imgTotal}</div>}
            </div>
          </div>
          <div style={{ display:"flex", gap:6, marginLeft:6 }}>
            {onPrev && (
              <button onClick={onPrev}
                style={{ padding:"10px 14px", borderRadius:999, border:"1.5px solid rgba(255,255,255,.5)", background:"rgba(0,0,0,.35)", cursor:"pointer", fontSize:12, fontWeight:700, color:"#fff", backdropFilter:"blur(6px)", whiteSpace:"nowrap" }}>
                ← Prev
              </button>
            )}
            {onNext && (
              <button onClick={onNext}
                style={{ padding:"10px 16px", borderRadius:999, border:"1.5px solid rgba(255,255,255,.5)", background:"rgba(0,0,0,.35)", cursor:"pointer", fontSize:13, fontWeight:700, color:"#fff", backdropFilter:"blur(6px)", whiteSpace:"nowrap" }}>
                Next ✦
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

/* ── Prompt copy button ── */
const PromptCopyButton = ({ prompt }) => {
  const [copied, setCopied] = React.useState(false);
  const copy = () => {
    const text = prompt || "";
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text).then(() => { setCopied(true); setTimeout(()=>setCopied(false),2500); });
    } else {
      const ta = document.createElement("textarea");
      ta.value = text; document.body.appendChild(ta); ta.select();
      document.execCommand("copy"); document.body.removeChild(ta);
      setCopied(true); setTimeout(()=>setCopied(false),2500);
    }
  };
  return (
    <button onClick={copy} className="btn-press" style={{
      width:"100%", padding:"12px", borderRadius:14, border:"none", cursor:"pointer", color:"#fff",
      fontFamily:"'Poppins',sans-serif", fontSize:13, fontWeight:700,
      display:"flex", alignItems:"center", justifyContent:"center", gap:8,
      background: copied ? "linear-gradient(135deg,#22C55E,#16A34A)" : "linear-gradient(135deg,#6C5CE7,#7C4DFF)",
      boxShadow: copied ? "0 4px 14px rgba(34,197,94,.4)" : "0 4px 14px rgba(108,92,231,.4)",
      transition:"all .25s cubic-bezier(.4,0,.2,1)",
    }}>
      <span style={{ fontSize:16 }}>{copied ? "✅" : "📋"}</span>
      {copied ? "Copied! Paste in Imagine AI" : "Copy Prompt for Imagine AI"}
    </button>
  );
};

function getRandomScene(level, excludeId = null) {
  // Use IMAGE_BANK so that the real embedded photos are shown (not SVG cartoons).
  // IMAGE_BANK entries have { id, imageUrl, scene, hint } — imageUrl is a base64 JPEG.
  const list = IMAGE_BANK[level] || IMAGE_BANK.A1;
  const available = excludeId ? list.filter(s => s.id !== excludeId) : list;
  return available[Math.floor(Math.random() * available.length)];
}

